[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles',[string]$OutputPath='ES/Output/WebPageStudio/webpagestudio-migration-report-v5.json')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$base=& (Join-Path $root 'ES/Automation/WebPageStudio/New-ESWebPageStudioMigrationReportV4.ps1') -BundlesDirectory $BundlesDirectory -OutputPath 'ES/Output/WebPageStudio/webpagestudio-migration-report-v4.json'|ConvertFrom-Json;$fresh=Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioFreshness.ps1';$rows=[System.Collections.Generic.List[object]]::new();foreach($d in @(Get-ChildItem -LiteralPath (Join-Path $root $BundlesDirectory) -Directory -Filter 'locale-bundle-refresh-v*'|Where-Object Name -notlike '*-offline')){foreach($c in @(Get-ChildItem -LiteralPath $d.FullName -Recurse -Filter 'web-page-contract.json' -File)){$r=& $fresh -ContractPath $c.FullName|ConvertFrom-Json;$check=$r.checks|? check -eq 'request-hash-closure';if($null -ne $check){$rows.Add([pscustomobject]@{contract=$c.FullName.Replace($root,'').Replace('\','/');status=$check.status})}}};$base|Add-Member -NotePropertyName requestHashClosure -NotePropertyValue ([pscustomobject]@{contractCount=$rows.Count;passedCount=(@($rows|? status -eq 'passed').Count);failedCount=(@($rows|? status -ne 'passed').Count);status=if(@($rows|? status -ne 'passed').Count -eq 0 -and $rows.Count -gt 0){'passed'}else{'partial'};contracts=$rows}) -Force;$out=[IO.Path]::GetFullPath((Join-Path $root $OutputPath));if(-not $out.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'OutputPath must remain under project root.'};[IO.File]::WriteAllText($out,($base|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));[pscustomobject]@{status=$base.status;reportPath=$out.Replace($root,'').Replace('\','/');closure=$base.requestHashClosure.status;contracts=$base.requestHashClosure.contractCount;passed=$base.requestHashClosure.passedCount}|ConvertTo-Json -Depth 8
